<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE']);$db=Database::connection();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$client=(int)$_POST['client_id'];queue_notification($db,$client,trim($_POST['objet']),trim($_POST['contenu']));audit('NOTIFICATION','client',$client);flash('success','Notification enregistrée dans la file d’envoi.');redirect('notifications/index.php');}$clients=$db->query("SELECT id,numero_client,COALESCE(raison_sociale,CONCAT(prenom,' ',nom)) nom FROM clients WHERE email IS NOT NULL AND email<>'' ORDER BY nom")->fetchAll();$rows=$db->query("SELECT n.*,COALESCE(c.raison_sociale,CONCAT(c.prenom,' ',c.nom)) client FROM notifications n LEFT JOIN clients c ON c.id=n.client_id ORDER BY n.date_programmee DESC LIMIT 100")->fetchAll();$title='Notifications';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Notifications e-mail</h1><p class="text-secondary">File d’envoi et historique</p></div></div><div class="alert alert-warning">L’envoi réel est désactivé par défaut. Configurez le serveur mail puis définissez <code>MAIL_ENABLED = true</code>.</div><form method="post" class="card card-body mb-3"><?= csrf_field() ?><div class="row g-2"><div class="col-md-3"><select class="form-select" name="client_id"><?php foreach($clients as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['numero_client'].' · '.$c['nom']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><input class="form-control" name="objet" placeholder="Objet" required></div><div class="col-md-4"><input class="form-control" name="contenu" placeholder="Message" required></div><div class="col-md-2"><button class="btn btn-primary w-100">Programmer</button></div></div></form><div class="card"><table class="table mb-0"><thead><tr><th>Date</th><th>Client</th><th>Objet</th><th>Canal</th><th>Statut</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['date_programmee']) ?></td><td><?= e($r['client']) ?></td><td><?= e($r['objet']) ?></td><td><?= e($r['canal']) ?></td><td><?= e($r['statut']) ?></td></tr><?php endforeach ?></tbody></table></div><?php require __DIR__.'/../../includes/footer.php'; ?>
